using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00008 : ControllerTestBase
    {
        private Regex genericTypeRegex = new Regex(@"<(.*)>");
        
        [TestMethod]
        public void Controller_Method_Should_Provide_At_Least_One_Ok_Status_Code()
        {
            var missingProduceResponseTypes = (from controller in Controllers
                                               where controller.Name.NotEqualsTo("HealthController")
                                               from method in controller.Methods
                                               where method.ReturnParameter.DoesNotContain("ActionResult")
                                               let attributes = method.Attributes.Where(a => a.Name.StartWith("ProducesResponseType"))
                                               let returnType = Regex.Matches(method.ReturnParameter, @"(?<=\<)(.*?)(?=\>)").FirstOrDefault()?.Value ?? method.ReturnParameter
                                               where attributes.Any(a => (a.Arguments.Any(arg => arg.Contains("Status20")) &&
                                                                          a.Arguments.Any(arg => arg.Contains(returnType)) &&
                                                                          a.Arguments.Any(arg => arg.Contains("typeof"))) ||
                                                                         ((method.ReturnParameter == nameof(Task) || method.ReturnParameter == nameof(ActionResult)) && a.Arguments.All(a => a.DoesNotContain("typeof")))).IsFalse()
                                               select new
                                               {
                                                   ErrorClass = controller.FullQualifiedName,
                                                   Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
MethodName: {method.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:     

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample: 

[ProducesResponseType(typeof({(returnType.IsEmpty() ? method.ReturnParameter : returnType)}), StatusCodes.Status200OK)]
{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                               }).ToImmutableList();

            Assert.IsTrue(missingProduceResponseTypes.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00008

Missing produce response type for OK result. Findings {missingProduceResponseTypes.Count}': {Environment.NewLine}{missingProduceResponseTypes.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
